use App\Models\Lib\Prosecutor;

class ProsecutorsTableSeeder extends Seeder
{
    /**
     * Run the database seeds.
     *
     * @return void
     */
    public function run()
    {
        $prosecutors = $this->getProsecutors();
        
        DB::beginTransaction();
        try{
            foreach($prosecutors as $prosecutor){
                if(!empty($prosecutor['Id_Kejaksaan'])){
                    /*$prosecutorExpression = Prosecutor::updateOrCreate(
                        [
                            'id' => $prosecutor['Id'],
                        ],
                        [
                            'id' => $prosecutor['Id'],
                            'emp_id' => $prosecutor['Id'],
    
                            'parent_id' => (isset($prosecutor['parent_id'])) ? (($prosecutor['parent_id'] == null || $prosecutor['parent_id'] == 0) ? null : $prosecutor['parent_id']) : null,
    
                            'class' => (isset($prosecutor['class'])) ? $prosecutor['class'] : null,
    
                            'name' => $prosecutor['Nama'],
                            'full_name' => $prosecutor['Nama'],
    
                            'satker_code' => (isset($prosecutor['satker_code'])) ? $prosecutor['satker_code'] : null,
                            'location_id'=> (!empty($prosecutor['location_id'])) ? $prosecutor['location_id'] : null,

                            'address' => $prosecutor['Alamat'],
                            'country_id' => 'C101',
                            'province_id' => ($prosecutor['PropinsiId']) ? 'P' . $prosecutor['PropinsiId'] : null,
                            'regency_id' => ($prosecutor['KotaId']) ? 'R' . $prosecutor['KotaId'] : null,
                            'district_id' => ($prosecutor['KecamatanId']) ? 'D' . $prosecutor['KecamatanId'] : null,
                            'village_id' => ($prosecutor['KelurahanId']) ? 'V' . $prosecutor['KelurahanId'] : null,
                            'postal_code' => $prosecutor['KodePos'],
                        ]
                    );*/

                    $prosecutorExpression = Prosecutor::updateOrCreate(
                        [
                            'id' => $prosecutor['Id_Kejaksaan'],
                        ],
                        [
                            'id' => $prosecutor['Id_Kejaksaan'],
                            'emp_id' => $prosecutor['Id_Kejaksaan'],
    
                            'parent_id' => (isset($prosecutor['parent_id'])) ? (($prosecutor['parent_id'] == null || $prosecutor['parent_id'] == 0) ? null : $prosecutor['parent_id']) : null,
    
                            'class' => (isset($prosecutor['class'])) ? $prosecutor['class'] : null,
    
                            'name' => strtoupper($prosecutor['Full_Nama']),
                            'full_name' => strtoupper($prosecutor['Full_Nama']),
    
                            'satker_code' => (isset($prosecutor['satker_code'])) ? $prosecutor['satker_code'] : null,
                            'location_id'=> (!empty($prosecutor['KecamatanId'])) ? 'D' . $prosecutor['KecamatanId'] : null,

                            'address' => $prosecutor['Nama_Jalan'],
                            'country_id' => 'C101',
                            'province_id' => ($prosecutor['PropinsiId']) ? 'P' . $prosecutor['PropinsiId'] : null,
                            'regency_id' => ($prosecutor['KotaId']) ? 'R' . $prosecutor['KotaId'] : null,
                            'district_id' => ($prosecutor['KecamatanId']) ? 'D' . $prosecutor['KecamatanId'] : null,
                            'village_id' => ($prosecutor['KelurahanId']) ? 'V' . $prosecutor['KelurahanId'] : null,
                            'postal_code' => $prosecutor['Kode_Pos'],
                        ]
                    );

                    $prosecutorExpression->polices()->detach();
    
                    if(isset($prosecutor['police_id']) && !empty($prosecutor['police_id']) && $prosecutor['police_id'] != 0 && $prosecutor['police_id'] != '-'){
                        $prosecutorExpression->polices()->attach($prosecutor['police_id']);
                    }
                }

            }
            DB::commit();

            $this->command->info('Prosecutors table seeded!');
        } catch(\Exception $e){
            DB::rollback();
            throw $e;
        }
        
    }

